use vstd::prelude::*;

verus! {
    // Specification: count the number of true entries in the boolean sequence.
    spec fn count_true(condition: Seq<bool>) -> nat
        decreases condition
    {
        if condition.len() == 0 {
            0
        } else if condition[0] {
            1 + count_true(condition.slice(1, condition.len()))
        } else {
            count_true(condition.slice(1, condition.len()))
        }
    }

    // extract: given a boolean mask and a parallel f32-array of equal length,
    // produce a new Vec<f32> containing exactly those arr[i] for which
    // condition[i] is true, in the same relative order.
    fn extract(condition: Vec<bool>, arr: Vec<f32>) -> (result: Vec<f32>)
        requires
            condition.len() == arr.len(),
        ensures
            // the length of the result matches the total number of trues
            result.len() as nat == count_true(condition.read()),
    {
        let n = condition.len();
        let mut result: Vec<f32> = Vec::new();
        let mut idx: usize = 0;
        while idx < n
            invariant
                // we never run off the end
                idx <= n,
                // the current result length matches the number of trues
                // in the prefix condition[0..idx]
                result.len() as nat == count_true(condition.read().slice(0, idx)),
            decreases n - idx,
        {
            if *condition.index(idx) {
                // by definition of count_true, appending one more true
                // raises the count by exactly 1
                assert(result.len() as nat + 1 ==
                       count_true(condition.read().slice(0, idx + 1)))
                by { }
                result.push(*arr.index(idx));
            } else {
                // if the mask is false, the count stays the same
                assert(result.len() as nat ==
                       count_true(condition.read().slice(0, idx + 1)))
                by { }
            }
            idx += 1;
        }
        result
    }
}

